cd scripts && python3 - <<'PY'
import ast, pathlib, collections
names = collections.defaultdict(set)
defs = {}
for f in pathlib.Path("lesson_deck").rglob("*.py"):
	tree = ast.parse(f.read_text())
	for node in ast.walk(tree):
		if isinstance(node, (ast.FunctionDef, ast.ClassDef)) and not node.name.startswith("__"):
			defs.setdefault(node.name, []).append(str(f))
		if isinstance(node, ast.Assign):
			for t in node.targets:
				if isinstance(t, ast.Name) and t.id.isupper():
					defs.setdefault(t.id, []).append(str(f))
		if isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name) and node.target.id.isupper():
			defs.setdefault(node.target.id, []).append(str(f))
src = "\n".join(p.read_text() for p in list(pathlib.Path(".").rglob("*.py")))
src += pathlib.Path("../src/domain/script/data/generatedDeck.test.ts").read_text()
for name, where in sorted(defs.items()):
	if src.count(name) <= len(where):
		print("possibly unused:", name, where)
PY
